#include <iostream>
#include <cmath>
#include <algorithm>

int main() {
    long long inputNumber;
    std::cin >> inputNumber;
    int digitCount = (inputNumber == 0) ? 1 : (int)std::floor(std::log10(std::abs(inputNumber))) + 1;

    auto createOnes = [](long long count) -> long long {
        return ((long long)std::pow(10, count) - 1) / 9;
    };

    std::function<long long(long long, int)> recursiveCount = [&](long long n, int length) -> long long {
        long long ones = createOnes(length);
        long long sum = (n / ones) * length;
        n %= ones;
        if (n == 0) return sum;
        long long optionA = (length + 1) + recursiveCount(ones - n, length - 1);
        long long optionB = recursiveCount(n, length - 1);
        return sum + std::min(optionA, optionB);
    };

    std::cout << recursiveCount(inputNumber, digitCount) << std::endl;
    return 0;
}
